package local.skyfamily;
import android.content.*;import android.graphics.*;import android.os.Handler;import android.view.*;import android.widget.*;
final class CastPanel extends LinearLayout implements SurfaceHolder.Callback {
 final CompanionActivity host;final Handler timer=new Handler();final TextView status;final SurfaceView surface;final ImageView image;final SeekBar seek;Bitmap showing;boolean attached=false;CastService service;
 CastPanel(CompanionActivity activity){super(activity);host=activity;setOrientation(1);TextView warning=host.paperText("Persistent DLNA/UPnP receiver, not Google Cast, AirPlay or Miracast. No pairing password: trusted LAN only. Receiver may fetch sender-provided HTTP(S) media URLs.",14,PaperActivity.MUTE);addView(warning);status=host.paperText("Starting receiver",16,PaperActivity.INK);addView(status);LinearLayout actions=new LinearLayout(host);addView(actions,new LayoutParams(-1,host.dp(54)));host.tool(actions,"Enable",()->{host.prefs.edit().putBoolean("cast.persistent",true).apply();host.startCast();});host.tool(actions,"Disable",()->{host.prefs.edit().putBoolean("cast.persistent",false).apply();host.stopService(new Intent(host,CastService.class));});FrameLayout stage=new FrameLayout(host);stage.setBackgroundColor(Color.BLACK);addView(stage,new LayoutParams(-1,0,1));surface=new SurfaceView(host);surface.getHolder().addCallback(this);stage.addView(surface,new FrameLayout.LayoutParams(-1,-1));image=new ImageView(host);image.setScaleType(ImageView.ScaleType.FIT_CENTER);stage.addView(image,new FrameLayout.LayoutParams(-1,-1));LinearLayout controls=new LinearLayout(host);addView(controls,new LayoutParams(-1,host.dp(54)));host.tool(controls,"Play",()->{if(service!=null)service.local("Play");});host.tool(controls,"Pause",()->{if(service!=null)service.local("Pause");});host.tool(controls,"Stop",()->{if(service!=null)service.local("Stop");});seek=new SeekBar(host);addView(seek);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(user&&service!=null)service.seek(value);}public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}});SeekBar volume=new SeekBar(host);volume.setMax(100);volume.setProgress(100);volume.setContentDescription("Receiver volume");addView(volume);volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(user&&service!=null)service.setVolume(value);}public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}});}
 final Runnable update=new Runnable(){public void run(){if(!attached)return;CastService current=CastService.instance;if(current!=service){if(service!=null)service.detach(surface.getHolder());service=current;}if(service==null){status.setText(host.prefs.getBoolean("cast.persistent",true)?"Receiver starting or unavailable":"Receiver disabled");image.setImageBitmap(null);showing=null;}else{status.setText(service.network()+"\n"+service.title+" / "+service.detail);if(surface.getHolder().getSurface().isValid())service.attach(surface.getHolder());image.setVisibility(service.photoMode?VISIBLE:GONE);if(showing!=service.photo){showing=service.photo;image.setImageBitmap(showing);}if(service.active!=null){seek.setMax((int)Math.min(Integer.MAX_VALUE,Math.max(1,service.active.duration)));seek.setProgress((int)Math.min(Integer.MAX_VALUE,service.active.position));}}timer.postDelayed(this,500);}};
 protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;timer.post(update);}
 protected void onDetachedFromWindow(){attached=false;timer.removeCallbacksAndMessages(null);if(service!=null)service.detach(surface.getHolder());service=null;image.setImageBitmap(null);showing=null;super.onDetachedFromWindow();}
 public void surfaceCreated(SurfaceHolder holder){if(service!=null)service.attach(holder);}public void surfaceChanged(SurfaceHolder holder,int format,int width,int height){if(service!=null)service.attach(holder);}public void surfaceDestroyed(SurfaceHolder holder){if(service!=null)service.detach(holder);}
}
